import React from 'react'
import { HeadFC, PageProps } from 'gatsby'
import { AuthProvider } from '../../../contexts/AuthContext'
import { Toaster } from 'react-hot-toast'
import { VenueAttendeesList } from '../../../components/attendance/VenueAttendeesList'
import { getVenueById } from '../../../data/venues'

interface VenuePageContext {
  venueId: string
}

interface VenuePageProps extends PageProps {
  pageContext: VenuePageContext
}

const VenuePage: React.FC<VenuePageProps> = ({ pageContext }) => {
  const { venueId } = pageContext
  const venue = getVenueById(venueId)
  
  return (
    <AuthProvider>
      <VenueAttendeesList 
        venueId={venueId} 
        venueName={venue?.name || venueId} 
      />
      <Toaster 
        position="top-right"
        toastOptions={{
          duration: 3000,
          style: {
            background: '#363636',
            color: '#fff',
          },
        }}
      />
    </AuthProvider>
  )
}

export const Head: HeadFC<any, VenuePageContext> = ({ pageContext }) => {
  const venue = getVenueById(pageContext.venueId)
  const title = venue ? `${venue.name} - 美辞学ナビ` : '美辞学ナビ'
  const description = venue 
    ? `${venue.name}（${venue.location.prefecture}）の参加予定者をチェック！`
    : 'Reol美辞学ツアーの会場詳細'

  return (
    <>
      <title>{title}</title>
      <meta name="description" content={description} />
      <meta property="og:title" content={title} />
      <meta property="og:description" content={description} />
      <meta property="og:type" content="website" />
    </>
  )
}

export default VenuePage